// Reads the bounces that come back to the envelope address (BOUNCE_ADDRESS).
// The MTA container accepts mail for that single address and posts each message to the
// application (/hooks/bounce). Most bounces are DSNs generated by Postfix itself when a
// remote server refuses a message it had queued.
//
// A bounce is believed only if it copies back the recipient's X-FeedNotice-Ref mark set at
// sending: a third party cannot forge a bounce to suspend an address.

import { normalizeEmail } from '../subscriptions.ts';
import type { MailEventType } from '../subscriptions.ts';
import { RECIPIENT_TAG_HEADER } from './mailer.ts';

export interface BounceEvent {
  email: string;
  type: Extract<MailEventType, 'hard_bounce' | 'soft_bounce'>;
}

export function parseBounce(raw: string, tagOf: (email: string) => string): BounceEvent[] {
  const text = raw.replace(/\r\n/g, '\n');
  // Complaint reports (ARF) are not handled here: without a feedback loop signed by the
  // mailbox provider, anyone could forge one to unsubscribe someone.
  if (/^Content-Type:\s*multipart\/report;[^\n]*report-type="?feedback-report/im.test(text)) return [];

  const candidates: BounceEvent[] = [];
  // Standard report (RFC 3464): one block per recipient.
  for (const block of text.split(/\n\s*\n/)) {
    const rcpt = /^(?:Final|Original)-Recipient:\s*rfc822;\s*<?([^\s>]+)>?/im.exec(block)?.[1];
    if (!rcpt) continue;
    const action = /^Action:\s*(\w+)/im.exec(block)?.[1]?.toLowerCase();
    const status = /^Status:\s*([245])\.\d{1,3}\.\d{1,3}/im.exec(block)?.[1];
    if (action === 'delayed' || action === 'delivered' || action === 'relayed' || action === 'expanded') continue;
    if (!action && !status) continue;
    candidates.push({ email: rcpt, type: status === '4' ? 'soft_bounce' : 'hard_bounce' });
  }
  // Exim-style bounce without a standard report.
  if (candidates.length === 0) {
    const m = /following address(?:\(es\))? failed:\s*\n\s*\n\s*<?([^\s>]+@[^\s>]+)>?/i.exec(text);
    if (m) candidates.push({ email: m[1], type: 'hard_bounce' });
  }

  const tags = new Set(
    [...text.matchAll(new RegExp(`^${RECIPIENT_TAG_HEADER}:\\s*(\\S+)`, 'gim'))].map((m) => m[1]),
  );
  const events: BounceEvent[] = [];
  for (const c of candidates) {
    const email = normalizeEmail(c.email);
    if (email && tags.has(tagOf(email))) events.push({ email, type: c.type });
  }
  return events;
}
